  "general.languageFailed": "Die Sprache konnte nicht gespeichert werden. {error}",
  "computer.introLinux": "Jeder Bot hat seinen eigenen Linux-Computer – einen vollständigen Desktop mit Browser, Terminal und eigenen Dateien, getrennt von allen anderen Bots und von diesem Server. Computer schlafen ein, wenn sie nichts tun, und wachen bei Bedarf auf; nichts darauf geht verloren. Du kannst jederzeit zusehen oder die Steuerung übernehmen.",
  "computer.introBrowser": "Jeder Bot bekommt seinen eigenen Browser auf diesem Server – ein privates Fenster, mit dem er Seiten öffnet, Formulare ausfüllt und liest, was auf dem Bildschirm steht. Du kannst jederzeit zusehen oder die Steuerung übernehmen.",
  "computer.noneTitle": "Kein Computer verfügbar",
  "computer.noneText": "Bots haben auf diesem Server noch keinen Bildschirm. Wer ihn betreibt, kann jedem Bot einen Linux-Computer geben (Docker plus Desktop-Image) oder eine Browser-Engine installieren. Alles andere funktioniert weiter.",
  "computer.statusLinux": "Linux-Computer · {open} von {max} wach",
