  "computer.resetConfirm": "Zurücksetzen bestätigen",
  "computer.footLinux_one": "Löschen entfernt diesen Computer mit allem, was darauf installiert und gespeichert ist, außer den Bibliotheksdateien des Bots; beim nächsten Mal wird ein sauberer erstellt. Nur {n} Computer kann gleichzeitig wach sein – der am längsten ungenutzte schläft ein.",
  "computer.footLinux_other": "Löschen entfernt diesen Computer mit allem, was darauf installiert und gespeichert ist, außer den Bibliotheksdateien des Bots; beim nächsten Mal wird ein sauberer erstellt. Bis zu {n} Computer können gleichzeitig wach sein – der am längsten ungenutzte schläft ein.",
  "computer.footBrowser_one": "Zurücksetzen schließt alle Seiten auf diesem Desktop und startet ihn neu. Nur {n} Bot kann gleichzeitig einen Desktop offen haben.",
  "computer.footBrowser_other": "Zurücksetzen schließt alle Seiten auf diesem Desktop und startet ihn neu. Bis zu {n} Bots können gleichzeitig einen Desktop offen haben.",
  "permissions.intro": "Feste Entscheidungen darüber, was deine Bots ohne Nachfrage tun dürfen. Zahlungen und Löschungen fragen immer – und ebenso, nachdem ein Bot Inhalte von außen gelesen hat, an jemanden zu schreiben, den du nie genannt hast, oder auf deinem eigenen Computer zu handeln –, egal, was hier gespeichert ist.",
  "permissions.emptyTitle": "Keine gespeicherten Berechtigungen",
  "permissions.emptyText": "Wenn du bei einer Freigabe „Immer erlauben“ wählst, wird das hier gespeichert, damit du es später rückgängig machen kannst.",
