  "vault.intro": "Speichere hier Anmeldedaten, damit sich deine Bots auf ihrem Computer bei Websites anmelden können. Ein Bot kann eine gespeicherte Anmeldung in eine Seite eintippen, sieht das Passwort aber nie – und fragt dich immer zuerst.",
