  "relay.intro": "Deine eigenen Computer, verknüpft mit der App Sklubot Relais. Ein Bot kann dort nur mit deinem OK auf den Bildschirm schauen, klicken, tippen und Befehle ausführen: hier gefragt und noch einmal auf dem Computer selbst.",
