  "relay.phoneTitle": "Ein Handy? (Android)",
  "relay.phoneSteps": "Installiere die Sklubot-Android-App (Einstellungen → Allgemein → Auf deinem Handy), schalte ihren Bedienungshilfen-Dienst ein, öffne dann in der App die Handy-Steuerung und schalte das Relais ein: Es zeigt einen Code, den du oben eingibst. Bots können dann Bildschirmfotos machen, tippen, wischen, schreiben und Apps öffnen, nach deinem Ja auf dem Handy; nie Befehle. iPhone: nicht möglich, iOS erlaubt es nicht.",
  "relay.phoneOpen": "Dieses Handy verknüpfen",
  "relay.phoneChip": "Handy · {platform}",
  "relay.phoneOfflineTitle": "Dieses Handy ist nicht verbunden",
