  "relay.phoneNoSessionText": "Keine Live-Ansicht auf einem Handy: Hier erscheint das letzte Bildschirmfoto, das ein Bot gemacht hat.",
  "relay.privacy": "Das Entfernen eines Computers trennt ihn sofort, und sein Schlüssel funktioniert nicht mehr. Jede Aktion wird auch in einem Protokoll auf dem Computer selbst festgehalten.",
  "relay.guard.title": "Sicherheitsregeln",
  "relay.guard.intro": "Was deine Bots auf diesem Computer nie tun können. Sklubot lehnt zuerst ab, dann lehnt der Computer auf seiner Seite noch einmal ab.",
  "relay.guard.terminal": "Terminal-Befehle (unter Steuerung)",
  "relay.guard.terminalOff": "Aus: Kein Bot kann auf diesem Computer einen Befehl ausführen.",
  "relay.guard.terminalOn": "An: Der Bot kann Befehle ausführen (zum Beispiel zum Programmieren). Jeder wird dir auf einer Karte mit seinem Ordner gezeigt; heikle (Löschen, Administratorrechte, Installation für den ganzen Computer…) werden immer gefragt, und der Computer fragt außerdem einmal pro Sitzung. Terminal-Fenster bleiben für Klicks und Tippen tabu.",
  "relay.guard.keepApps": "Apps außer Reichweite halten",
  "relay.guard.keepAppsPh": "Eine pro Zeile, zum Beispiel:\nMeine Bank\nSignal",
  "relay.guard.keepFolders": "Ordner außer Reichweite halten",
  "relay.guard.keepFoldersPh": "Einer pro Zeile, zum Beispiel:\n~/Steuern\nMedizinisch",
  "relay.guard.keepHint": "Der Bot kann in diesen Apps oder in einem Fenster mit diesen Ordnern weder klicken noch tippen und diese Ordner nicht lesen. Höchstens {n} Zeilen pro Liste.",
  "relay.guard.projects": "Projektordner",
  "relay.guard.projectsPh": "Einer pro Zeile, zum Beispiel:\n~/projects/site",
  "relay.guard.projectsHint": "Befehle laufen im ersten Ordner, wenn der Bot keinen angibt. Ein Befehl anderswo wird immer gefragt.",
  "relay.guard.timeout": "Maximale Laufzeit eines Befehls (Sekunden)",
  "relay.guard.timeoutHint": "Zwischen {min} und {max} Sekunden. Danach wird der Befehl gestoppt (außer Hintergrundbefehle, die mit der Sitzung enden).",
  "relay.guard.floor": "Immer gefragte Befehle",
  "relay.guard.floorText": "Egal, was du vorher erlaubt hast: Diese Befehle fragen jedes Mal nach deinem Ja, hier und auf dem Computer:",
  "relay.guard.floor.delete": "Löschen oder Überschreiben (rm -r, del /s, find -delete, git reset --hard…)",
  "relay.guard.floor.git": "Git-Verlauf umschreiben (push --force, branch -D…)",
  "relay.guard.floor.admin": "Administratorrechte (sudo, su, runas, doas)",
  "relay.guard.floor.install": "Software für den ganzen Computer installieren oder entfernen (apt, brew, winget, npm -g…)",
  "relay.guard.floor.disk": "Festplatten und Partitionen (diskutil, diskpart, fdisk, mount…)",
