  "settings.section.rules": "Regeln",
  "rules.intro": "Schreib mit eigenen Worten, was deine Bots tun dürfen oder nicht. Sie befolgen diese Regeln überall (Chat, Aufgaben, Routinen), und im Modus „Auto“ prüft ein Prüfer jede heikle Aktion daran.",
