  "skl.gh.intro": "Füge die Adresse eines öffentlichen GitHub-Repositorys (oder eines seiner Ordner) ein: Sklubot listet die Fähigkeiten (SKILL.md-Dateien) darin mit ihrer Lizenz auf. Nichts wird gespeichert, bis du wählst; importierte Fähigkeiten kommen als Entwürfe an, die du nach dem Lesen im Tab „Fähigkeiten“ jedes Bots aktivierst.",
