  "memset.intro": "Was sich deine Bots merken, lernen sie nur aus deinen eigenen Nachrichten – nie aus E-Mails, Seiten oder ihren eigenen Antworten. Jede gelernte Notiz behält die Worte, aus denen sie stammt.",
