  "realtime.title": "Echtzeit-Sprachmodell (Option)",
  "realtime.text": "Anrufe antworten in einem Bruchteil einer Sekunde. Der Bot macht trotzdem die Arbeit: Das Sprachmodell gibt jede Anfrage an ihn weiter und liest seine Antwort vor. Standardmäßig aus.",
