  "media.heading": "Erstellung (Bilder und Videos)",
  "media.intro": "Deine eigenen Schlüssel, um Bilder und Videos zu erstellen, und deine GPU (Wan2GP), um sie kostenlos zu erstellen. Ein Schlüssel wird nie wieder angezeigt und nur deine Bots nutzen ihn, für dein Konto.",
