  "media.job.cancelled": "gestoppt",
  "egress.accountIntro": "Programme auf dem Computer eines Bots können deine APIs aufrufen, ohne den Schlüssel je zu halten: Schalte es pro Bot ein (Bot-Einstellungen → Lesen & Schlüssel). Sklubot fügt den Schlüssel außerhalb des Computers hinzu, nur für die Hosts, für die er gespeichert ist, und fragt dich vor der ersten Nutzung jedes Schlüssels.",
  "egress.toggle": "Programme dürfen meine Schlüssel nutzen",
  "egress.intro": "Skripte und Tools, die {name} auf seinem Computer ausführt, können über Sklubot APIs mit deinen gespeicherten Secrets aufrufen. Der Schlüssel kommt nie auf den Computer; nur die Hosts jedes Secrets funktionieren; die erste Nutzung jedes Secrets und Änderungen nach Inhalten von außen fragen dich.",
