  "dl.title": "Sklubot herunterladen",
  "dl.intro": "Dein Sklubot in einer echten App: eigenes Fenster, Benachrichtigungen und ein Symbol in der Taskleiste. Auf einem Computer ist das Relais eingebaut, damit deine Bots deinen Rechner steuern können – nur mit deiner Zustimmung.",
