  "dl.windows": "Windows 10 und 11",
  "dl.windows.hint": "Starte das Installationsprogramm. Wenn Windows „Der Computer wurde durch Windows geschützt“ meldet, klicke auf „Weitere Informationen“ und dann auf „Trotzdem ausführen“. Die .zip läuft ohne Installation.",
  "dl.mac": "macOS 11 oder neuer",
  "dl.mac.hint": "Öffne die .dmg und zieh Sklubot in den Ordner Programme. Wenn macOS sich beim ersten Mal weigert, sie zu öffnen: Systemeinstellungen › Datenschutz & Sicherheit › „Dennoch öffnen“.",
