  "teamFolder.restart": "Jeder Computer bekommt (oder verliert) ihn beim nächsten Start: nachdem er geschlafen hat oder wenn du ihn neu startest. Er wird dann aus seinem Image neu erstellt: Sein Home-Ordner (Dateien, Anmeldungen, Einstellungen) und seine Bibliothek bleiben erhalten; außerhalb des Home-Ordners installierte Programme müssen neu installiert werden.",
