  "shared.heading": "Geteilte Computer",
  "shared.intro": "Bots, die in ihren Einstellungen auf „Geteilt“ stehen (Allgemein → Computer), arbeiten auf diesen Computern statt auf ihrem eigenen: dieselben Dateien, derselbe Browser, dieselben Claude- und ChatGPT-Anmeldungen. Immer nur ein Bot steuert einen Computer; die anderen warten. Jeder Bot behält seine eigene Bibliothek unter ~/files.",
