  "recovery.title": "Passwort vergessen",
  "recovery.intro": "Gib die E-Mail-Adresse deines Kontos ein. Wenn ein Konto sie nutzt, bekommst du einen Link, um ein neues Passwort zu wählen (30 Minuten gültig).",
