  "recovery.noMailTitle": "Dieser Server kann keine E-Mails senden",
  "recovery.noMail": "Bitte die Person, die diesen Sklubot-Server betreibt, dir ein neues Passwort zu geben.",
  "recovery.noMailOwner": "Wenn du das bist: Öffne ein Terminal im Sklubot-Container des Servers (mit Coolify: dein Sklubot-Dienst → Terminal) und führe diesen Befehl mit deiner Adresse aus. Er gibt ein neues Passwort aus und meldet alle Geräte ab.",
