  "smtp.title": "Server-E-Mails",
  "smtp.intro": "Das E-Mail-Konto, mit dem dieser Sklubot seine eigenen E-Mails sendet: Links für „Passwort vergessen?“ und Adressänderungen. Nur du, der Betreiber des Servers, siehst das.",
  "smtp.statusOn": "An: Der Server kann E-Mails senden.",
  "smtp.statusOff": "Nicht eingerichtet: „Passwort vergessen?“ sagt den Leuten nur, dass sie dich fragen sollen.",
  "smtp.fromEnv": "Diese Einstellungen kommen aus der Umgebung des Servers (SMTP_HOST, SMTP_PORT, SMTP_TLS, SMTP_USER, SMTP_PASS, SMTP_FROM) und haben Vorrang vor dieser Seite. Um sie zu ändern, bearbeite sie dort.",
  "smtp.guideTitle": "Hilfe für gängige Anbieter",
  "smtp.gmail1": "Schalte die Bestätigung in zwei Schritten in deinem Google-Konto ein (myaccount.google.com → Sicherheit).",
  "smtp.gmail2": "Erstelle ein App-Passwort unter myaccount.google.com/apppasswords (nenne es „Sklubot“) und kopiere seine 16 Zeichen.",
  "smtp.gmail3": "Hier: Server smtp.gmail.com, SSL/TLS, Port 465; Benutzername und Absender = deine Gmail-Adresse; Passwort = das App-Passwort.",
  "smtp.brevo": "Server smtp-relay.brevo.com, STARTTLS, Port 587. Benutzername und Passwort: das SMTP-Login und ein SMTP-Schlüssel aus Brevo → Einstellungen → SMTP & API (ein SMTP-Schlüssel, kein API-Schlüssel). Der Absender muss ein in Brevo bestätigter Absender sein.",
  "smtp.ovh": "Server ssl0.ovh.net (oder smtp.mail.ovh.net), SSL/TLS, Port 465. Benutzername und Absender = deine vollständige OVH-E-Mail-Adresse; Passwort = das Passwort dieses Postfachs.",
