  "backup.title": "Automatische Sicherung",
  "backup.intro": "Jede Nacht sendet Sklubot selbst eine verschlüsselte Kopie seiner Daten an einen S3-Speicher außerhalb dieses Servers (OVHcloud, Hetzner, Scaleway…). Nur du (der den Server betreibt) siehst diese Einstellung.",
  "backup.statusOn": "An: Jede Nacht geht eine Sicherung raus.",
  "backup.statusPaused": "Pausiert: Keine Sicherung ist geplant.",
  "backup.statusOff": "Nicht eingerichtet.",
  "backup.homesNote": "Die Computer der Bots sind nicht enthalten: Installationen und Anmeldungen (Claude, ChatGPT…) müssen nach einer Wiederherstellung neu gemacht werden. Das SSH-Skript deploy/backup.sh enthält sie.",
