  "backup.inProgress": "läuft…",
  "backup.step1": "Der Sicherungsschlüssel",
  "backup.keyWhy": "Sicherungen werden verschlüsselt, bevor sie diesen Server verlassen. Hier erstellst du einen zweiteiligen Schlüssel: Der öffentliche Teil bleibt auf dem Server (er kann nur verschlüsseln), der private Teil bleibt bei dir (nur er kann wiederherstellen). Selbst wer den Server oder den Speicher nimmt, kann deine Sicherungen nicht lesen.",
  "backup.makeKey": "Meinen Sicherungsschlüssel erstellen",
  "backup.noWebCrypto": "Dieser Browser kann den Schlüssel nicht erstellen. Öffne diese Seite in einem aktuellen Browser (aktuelles Chrome, Firefox, Safari) oder füge einen öffentlichen age-Schlüssel ein.",
  "backup.havePublicKey": "Ich habe schon einen age-Schlüssel: seinen öffentlichen Schlüssel einfügen",
  "backup.publicKey": "Öffentlicher age-Schlüssel",
  "backup.publicKeyHint": "Beginnt mit age1… (age-keygen zeigt ihn an). Bewahre den privaten Schlüssel außerhalb des Servers auf.",
  "backup.saveKeyTitle": "Speichere diesen privaten Schlüssel jetzt.",
  "backup.saveKeyText": "Ohne ihn kann niemand die Sicherungen wiederherstellen. Lade die Datei herunter und bewahre sie sicher auf (Passwort-Manager, USB-Stick, dein Computer), nicht nur auf diesem Server. Er wird nie wieder angezeigt.",
  "backup.download": "Datei herunterladen",
  "backup.copy": "Kopieren",
  "backup.keySavedCheck": "Ich habe diesen privaten Schlüssel sicher gespeichert, außerhalb dieses Servers.",
  "backup.useKey": "Diesen Schlüssel verwenden",
  "backup.keyReady": "Schlüssel bereit. Fülle den Speicher aus und speichere dann.",
