  "backup.keptHint": "Gespeichert ({hint})",
  "backup.keysHint": "Verschlüsselt auf dem Server, nie an den Browser zurückgeschickt (leer lassen, um die gespeicherten zu behalten). Nutze einen auf diesen Bucket beschränkten Schlüssel, wenn dein Anbieter es erlaubt.",
