  "backup.docBucket": "Bucket erstellen",
  "backup.docKeys": "Schlüssel erstellen",
  "backup.guide.ovh.title": "Bucket und Schlüssel bei OVHcloud erstellen (vom Handy)",
  "backup.guide.ovh.1": "OVHcloud Control Panel → Public Cloud → dein Projekt → Storage → Object Storage.",
  "backup.guide.ovh.2": "Tab „Users“: Erstelle einen Object-Storage-Benutzer. Notiere den Zugangsschlüssel und den geheimen Schlüssel (Button … → „View the secret key“).",
  "backup.guide.ovh.3": "Tab „Containers“ → „Create an object container“: Typ „S3-compatible API“, ein kleingeschriebener Name (z. B. sklubot-backups), eine Region (z. B. Gravelines = gra), den Benutzer verknüpfen, dann „Create“.",
  "backup.guide.ovh.4": "Hier: Wähle dieselbe Region, den Bucket-Namen, den Zugangsschlüssel und den geheimen Schlüssel, dann „Verbindung testen“.",
  "backup.guide.hetzner.title": "Bucket und Schlüssel bei Hetzner erstellen (vom Handy)",
  "backup.guide.hetzner.1": "Hetzner Console → dein Projekt → Object Storage → „Create Bucket“: ein Standort (z. B. Falkenstein = fsn1), ein eindeutiger Name, Sichtbarkeit „private“, dann „Create & Buy now“.",
  "backup.guide.hetzner.2": "Menü „Security“ → Tab „S3 Credentials“ → „Generate credentials“, mit einer Beschreibung (z. B. Sklubot).",
  "backup.guide.hetzner.3": "Kopiere sofort den Zugangsschlüssel (oben) und den geheimen Schlüssel (unten): Der geheime Schlüssel wird nicht noch einmal angezeigt.",
  "backup.guide.hetzner.4": "Hier: Wähle denselben Standort, den Bucket-Namen und beide Schlüssel, dann „Verbindung testen“.",
  "backup.guide.scaleway.title": "Bucket und Schlüssel bei Scaleway erstellen (vom Handy)",
  "backup.guide.scaleway.1": "Scaleway-Konsole → Object Storage → „+ Create bucket“: eine Region (z. B. Paris = fr-par), ein Name, Sichtbarkeit „Private“, dann „Create bucket“.",
  "backup.guide.scaleway.2": "Kontomenü (oben rechts) → „IAM & API keys“ → Tab „API keys“ → „+ Generate API key“.",
  "backup.guide.scaleway.3": "Wähle für Object Storage das Projekt des Buckets als bevorzugtes Projekt, dann „Generate API key“. Kopiere den Zugangsschlüssel und den geheimen Schlüssel (einmal angezeigt).",
  "backup.guide.scaleway.4": "Hier: Wähle dieselbe Region, den Bucket-Namen und beide Schlüssel, dann „Verbindung testen“.",
