  "caps.diffCaps": "Grenzen: pro Tag oder pro Monat (deine Zeitzone), in Dollar oder Tokens, für das Konto oder einen Bot; sie stoppen nur unbeaufsichtigte Arbeit oder alles. Mehrere können gelten: Die zuerst erreichte stoppt die Arbeit.",
