  "botApi.intro": "Lass deine eigenen Programme, Skripte oder einen KI-Client (Claude Code, Claude Desktop, Cursor…) mit einem Schlüssel mit {name} sprechen. Jeder Schlüssel gehört nur zu diesem Bot.",
  "botApi.safety": "Ein Programm ist nie du: Was es sendet, zählt als Inhalt von außen, nie als deine eigenen Worte. Alles, was nicht rückgängig gemacht werden kann (Senden, Zahlen, Löschen, Veröffentlichen), wartet hier immer auf dein Ja. Ein Schlüssel kann nie eine Freigabe beantworten, löschen, Einstellungen ändern, den Tresor oder Connectoren öffnen oder einen anderen Bot erreichen.",
