  "lp.what.title": "Kein weiterer Chatbot. Teamkollegen mit einer echten Aufgabe.",
  "lp.what.sub": "Ein Sklubot-Bot tut mehr als antworten: Er hat Tools, behält den Überblick und erledigt tatsächlich Arbeit.",
  "lp.f.job.t": "Eine Aufgabe",
  "lp.f.job": "Eine Rolle, Anweisungen, Fähigkeiten. Beschreib seine Aufgabe in ein paar Zeilen oder starte mit einer fertigen Vorlage.",
  "lp.f.memory.t": "Ein Gedächtnis",
  "lp.f.memory": "Er merkt sich, was du ihm beibringst: deine Kunden, deine Vorlieben, wie du schreibst. Du liest und löschst, was du willst.",
