  "lp.f.voice.t": "Eine eigene Stimme",
  "lp.f.voice": "Ruf deinen Bot an und sprich mit ihm wie am Telefon. Er antwortet laut, mit der Stimme, die du für ihn gewählt hast.",
  "lp.f.pc.t": "Ein eigener Computer",
  "lp.f.pc": "Ein isolierter Linux-Computer mit Browser, um zu suchen, Formulare auszufüllen und Dateien vorzubereiten. Du siehst seinen Bildschirm live.",
  "lp.f.pc.pool": "Im kostenlosen Tarif wird der Computer für eine Aufgabe geliehen und dann gelöscht.",
