  "lp.price.all": "Preisdetails",
  "lp.trust.kicker": "Vertrauen",
  "lp.trust.title": "So gebaut, dass du ihm echte Arbeit geben kannst.",
  "lp.trust.t1t": "Getrennte Konten",
  "lp.trust.t1": "Jedes Konto sieht nur seine eigenen Bots, Dateien und Unterhaltungen. Die Computer der Bots sind getrennte Container in einem Netzwerk, in dem sie sich nicht sehen können.",
  "lp.trust.t2t": "Verschlüsselte Geheimnisse",
  "lp.trust.t2": "App-Verbindungen und gespeicherte Passwörter werden auf dem Server verschlüsselt (AES-256-GCM).",
  "lp.trust.t3t": "Freie Software, in Europa hostbar",
  "lp.trust.t3": "Sklubot steht unter der MIT-Lizenz und läuft auf dem Server deiner Wahl, in Frankreich oder anderswo in Europa.",
  "lp.trust.t4t": "Du behältst die Kontrolle",
  "lp.trust.t4": "Ein Protokoll jeder Aktion, ein Pause-Button, Ausgabegrenzen und dein Okay vor allem, was nicht rückgängig gemacht werden kann.",
  "lp.faq.kicker": "FAQ",
  "lp.faq.title": "Fragen, die man uns stellt.",
  "lp.faq.q1": "Was ist ein Bot bei Sklubot?",
  "lp.faq.a1": "Ein KI-Assistent mit einer Rolle, einem Gedächtnis, Tools und je nach Tarif einem Computer. Du sprichst mit ihm wie mit einem Kollegen; er kann auch selbstständig arbeiten, nach einer geplanten Routine oder auf ein Ziel hin.",
  "lp.faq.q2": "Kann ein Bot Mist bauen?",
  "lp.faq.a2": "Ein neuer Bot ist vorsichtig: Er fragt, bevor er handelt. Bei allem, was nicht rückgängig gemacht werden kann (Senden, Zahlen, Löschen, Veröffentlichen), hält er an und wartet auf dein Okay, ohne „immer erlauben“. Du kannst ihn jederzeit pausieren.",
  "lp.faq.q3": "Kann ich wirklich mit meinen Bots sprechen?",
  "lp.faq.a3": "Ja: Ruf einen Bot aus seiner Unterhaltung an und sprich laut mit ihm. Er antwortet mit der Stimme, die du für ihn gewählt hast. Du kannst ihm auch schreiben, wann immer du willst.",
  "lp.faq.q4": "Muss ich etwas installieren?",
  "lp.faq.a4": "Nein: Alles funktioniert im Browser, auf einem Computer oder Handy. Wenn du lieber willst, gibt es eine App für Windows und Linux und eine für Android.",
  "lp.faq.q5": "Windows warnt mich, wenn ich die App installiere. Ist das normal?",
  "lp.faq.a5": "Ja. Die App ist noch nicht signiert, daher zeigt Windows SmartScreen beim ersten Mal eine Warnung. Klicke auf „Weitere Informationen“ und dann auf „Trotzdem ausführen“. Du kannst Sklubot auch online nutzen, ganz ohne Installation.",
  "lp.faq.q6": "Welche KI-Modelle werden genutzt?",
  "lp.faq.a6": "Die KI-Modelle, die dieser Dienst anbietet, oder dein eigener API-Schlüssel, wenn du das lieber willst. Jeder Bot kann sein eigenes Modell und Ersatzmodelle haben.",
  "lp.faq.q7": "Wo sind meine Daten?",
  "lp.faq.a7": "Auf dem Server dieses Dienstes. In den Einstellungen kannst du deine Daten jederzeit exportieren oder dein Konto löschen.",
  "lp.faq.q8": "Warum meine E-Mail-Adresse bestätigen?",
  "lp.faq.a8": "Um sicherzugehen, dass du es wirklich bist, und um dir zu helfen, falls du dein Passwort vergisst. Du kannst dich sofort umsehen; deine Bots fangen an zu arbeiten, sobald sie bestätigt ist.",
  "lp.final.title": "Dein Team wartet.",
  "lp.final.sub": "Erstelle dein Konto, wähle eine Vorlage, gib eine erste Aufgabe ab.",
  "lp.foot.tag": "Ein Team aus KI-Bots, mit Gedächtnis, Tools, Computer und Stimme.",
  "lp.foot.terms": "AGB",
